mapper.select:
select psk.* from product_sku psk inner join product p on psk.product_id = p.id
and psk.sku_name like CONCAT('%', #{keyword}, '%')
and p.brand_id = #{brandId}
and p.category1_id = #{category1Id}
and p.category2_id = #{category2Id}
and p.category3_id = #{category3Id}
and p.status = 1 and p.audit_status = 1 and psk.is_deleted = 0 and p.is_deleted = 0
order by psk.sale_num desc
order by psk.sale_price asc
order by psk.sale_price desc
order by psk.id desc
limit #{offset}, #{limit}

select count(*)
from product_sku psk
inner join product p on psk.product_id = p.id


        and psk.sku_name like CONCAT('%', #{keyword}, '%')


        and p.brand_id = #{brandId}


        and p.category1_id = #{category1Id}


        and p.category2_id = #{category2Id}


        and p.category3_id = #{category3Id}

    and p.status = 1
    and p.audit_status = 1
    and psk.is_deleted = 0
    and p.is_deleted = 0
